MEDICAL = [
    ('Subang Jaya Medical Centre (SJMC)', '🌟💫 Flagship Medical Tourism Hospital setting the gold standard! Part of Ramsay Sime Darby Healthcare, SJMC offers 600+ beds with cutting-edge technology and internationally accredited specialists. Renowned for complex surgeries, oncology, and cardiology. International patients receive VIP treatment with dedicated liaison officers. Where innovation meets compassion! 🏆', 'Oncology, Cardiology, Neurosurgery, Orthopedics, Fertility', 'https://www.ramsaysimedarby.com/sjmc', 'https://www.google.com/maps/search/Subang%20Jaya%20Medical%20Centre%20(SJMC)%20Malaysia', 'Selangor', '22 km', '30-45 min', 3.0854, 101.5156),
    ('Gleneagles Kuala Lumpur', '💎🌟 Premium healthcare in the heart of KL! This luxury hospital combines world-class medical expertise with five-star hospitality. Specialists trained globally, state-of-the-art facilities, and personalized care for international patients. From health screening to complex treatments, experience healthcare fit for royalty. Located in prestigious Ampang Hilir. ✨🏥', 'Health Screening, Cardiology, Orthopedics, Cosmetic Surgery, Oncology', 'https://www.gleneagles.com.my', 'https://www.google.com/maps/search/Gleneagles%20Kuala%20Lumpur%20Malaysia', 'Kuala Lumpur', '3 km', '10-15 min', 3.1262, 101.6771),
    ('Prince Court Medical Centre', "👑💫 NEXT to Petronas Twin Towers - healthcare meets iconic location! JCI-accredited with world-class facilities and specialists. Known for cosmetic surgery, fertility treatments, and executive health screening. International Patient Centre with multilingual staff ensures seamless experience. Heal with a view of Malaysia's famous skyline! 🏙️❤️", 'Cosmetic Surgery, Fertility, Executive Health, Orthopedics, Cardiology', 'https://www.princecourt.com', 'https://www.google.com/maps/search/Prince%20Court%20Medical%20Centre%20Malaysia', 'Kuala Lumpur', '2.5 km', '8-15 min', 3.1292, 101.6571),
    ('Sunway Medical Centre', "☀️🏥 Part of the renowned Sunway Group - excellence in education, leisure, AND healthcare! JCI-accredited facility with comprehensive services and research focus. Known for fertility, oncology, and robotic surgery. Connected to Sunway City's ecosystem of hotels, malls, and university. A complete healing experience! 🌈", 'Fertility IVF, Oncology, Robotic Surgery, Neurology, Cardiology', 'https://www.sunwaymedical.com', 'https://www.google.com/maps/search/Sunway%20Medical%20Centre%20Malaysia', 'Selangor', '18 km', '25-40 min', 3.1017, 101.5452),
    ('KPJ Healthcare', "🏥🌏 Malaysia's LARGEST private healthcare group with 29 hospitals nationwide! From bustling KL to serene Penang and strategic Johor - world-class care is never far. Specializing in medical tourism with dedicated international patient services. Consistent quality, affordable excellence, and the warmth of Malaysian hospitality across the nation! 💚", 'Multi-specialty, Medical Tourism Services, Health Screening, Surgery', 'https://www.kpjhealth.com.my', 'https://www.google.com/maps/search/KPJ%20Healthcare%20Malaysia', 'Selangor (KPJ Damansara)', '12 km', '20-30 min', 3.073, 101.5107),
    ('Malaysia Healthcare Travel Council (MHTC)', "🌍💼 Your OFFICIAL gateway to Malaysia medical tourism! Government agency connecting international patients with accredited hospitals and specialists. Concierge services from documentation to airport coordination. MYMT 2026 - Malaysia Year of Medical Tourism! Ambassador: Dato' Seri Siti Nurhaliza. 'Healing Meets Hospitality' - experience world-class care with Malaysian warmth. 🇲🇾❤️", 'Patient Coordination, Hospital Matching, Visa Assistance, Concierge Services', 'https://www.malaysiahealthcare.org', 'https://www.google.com/maps/search/Malaysia%20Healthcare%20Travel%20Council%20(MHTC)%20Malaysia', 'Kuala Lumpur', '30 km', '35-50 min', 3.1316, 101.6823),
    ('Island Hospital Penang', '🏝️🏆 Flagship Medical Tourism Hospital in UNESCO heritage city! This multi-specialty powerhouse offers comprehensive medical services with 600+ beds and state-of-the-art facilities. Known for oncology, orthopedics, and fertility treatments. International patients enjoy seamless care with dedicated patient coordinators and healing in historic George Town. Excellence meets hospitality! 🌟', 'Oncology, Orthopedics, Fertility, Neurology, Cardiology', 'https://www.islandhospital.com', 'https://www.google.com/maps/search/Island%20Hospital%20Penang%20Malaysia', '', '', '', 3.1405, 101.6894),
    ('Mahkota Medical Centre', "🏥🌏 Johor's medical tourism flagship serving Singapore, Indonesia, and beyond! Strategic location makes world-class healthcare accessible. Comprehensive services from health screening to complex surgeries. Renowned for orthopedics, oncology, and wellness programs. International Patient Centre ensures smooth experience. Just minutes from Singapore - quality care, Malaysian prices! 💎", 'Orthopedics, Oncology, General Surgery, Health Screening, Wellness', 'https://www.mahkotamedical.com', 'https://www.google.com/maps/search/Mahkota%20Medical%20Centre%20Malaysia', '', '', '', 3.1676, 101.6915),
]

